CREATE TABLE IF NOT EXISTS admins(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(180) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,category VARCHAR(100) NOT NULL,price DECIMAL(10,2) NOT NULL DEFAULT 0,compare_price DECIMAL(10,2) NULL,badge VARCHAR(80) NULL,description TEXT NULL,sizes_json JSON NULL,colors_json JSON NULL,image_url TEXT NULL,gallery_json JSON NULL,stock INT NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_category(category),INDEX idx_active(active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_no VARCHAR(40) NOT NULL UNIQUE,customer_name VARCHAR(180) NOT NULL,customer_phone VARCHAR(50) NOT NULL,customer_email VARCHAR(180) NOT NULL,total DECIMAL(10,2) NOT NULL DEFAULT 0,status VARCHAR(40) NOT NULL DEFAULT 'new',payment_status VARCHAR(40) NOT NULL DEFAULT 'pending',shipping_status VARCHAR(40) NOT NULL DEFAULT 'pending',address TEXT NULL,items_json JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_status(status),INDEX idx_created(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
